import axios from 'axios';

// Backend runs on localhost:5000
const api = axios.create({
  baseURL: 'http://localhost:5000/api',
});

// ── STATUS ───────────────────────────────────────────
export const statusAPI = {
  getStatus: () => api.get('/status'),
  getStats: () => api.get('/stats'),
};

// ── PRODUCTS / DATA ──────────────────────────────────
export const productsAPI = {
  getRandom: (n = 12) => api.get(`/random?n=${n}`),
  search: (query, top_n = 20) =>
    api.get(`/search?q=${encodeURIComponent(query)}&top_n=${top_n}`),
  getTop: (n = 20, min_trust = 0.6) =>
    api.get(`/top?n=${n}&min_trust=${min_trust}`),
};

// ── RECOMMENDATIONS ──────────────────────────────────
export const recsAPI = {
  getSimilar: (asin, top_n = 5, min_trust = 0.45) =>
    api.get(`/similar/${asin}?top_n=${top_n}&min_trust=${min_trust}`),

  getTrust: (asin) =>
    api.get(`/check/${asin}`),
};

// ── EXPORT DEFAULT ───────────────────────────────────
export default api;
